import React, { useEffect } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { Box, CircularProgress } from '@mui/material';

// Pages
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import Profile from './pages/Profile';
import EmergencyContacts from './pages/EmergencyContacts';
import AlertHistory from './pages/AlertHistory';
import Settings from './pages/Settings';
import Chat from './pages/Chat';
import AdminDashboard from './pages/AdminDashboard';

// Components
import ProtectedRoute from './components/ProtectedRoute';
import Notification from './components/Notification';
import PWAInstallPrompt from './components/PWAInstallPrompt';

// Services
import { getCurrentUser } from './store/slices/authSlice';
import socketService from './services/socketService';

function App() {
  const dispatch = useDispatch();
  const { isAuthenticated, isLoading, user } = useSelector((state) => state.auth);
  const { mode } = useSelector((state) => state.theme);

  useEffect(() => {
    // Set theme on app load
    document.documentElement.setAttribute('data-theme', mode);
  }, [mode]);

  useEffect(() => {
    // Check if user is authenticated on app load
    const token = localStorage.getItem('token');
    if (token && !isAuthenticated) {
      dispatch(getCurrentUser());
    }
  }, [dispatch, isAuthenticated]);

  useEffect(() => {
    // Connect to socket when user is authenticated
    if (isAuthenticated && user) {
      socketService.connect(user.id);

      // Listen for emergency broadcasts
      socketService.onEmergencyBroadcast((data) => {
        // Show notification for emergency alerts
        if ('Notification' in window && Notification.permission === 'granted') {
          new Notification('Emergency Alert Nearby', {
            body: `${data.userName} needs help in your area`,
            icon: '/logo192.png',
            tag: 'emergency-alert',
          });
        }
      });

      // Listen for nearby emergencies
      socketService.onNearbyEmergency((data) => {
        if ('Notification' in window && Notification.permission === 'granted') {
          new Notification('Nearby Emergency', {
            body: data.message,
            icon: '/logo192.png',
            tag: 'nearby-emergency',
          });
        }
      });

      return () => {
        socketService.disconnect();
      };
    }
  }, [isAuthenticated, user]);

  useEffect(() => {
    // Request notification permission
    if ('Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission();
    }
  }, []);

  if (isLoading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="100vh"
        bgcolor="background.default"
      >
        <CircularProgress size={60} />
      </Box>
    );
  }

  return (
    <Box minHeight="100vh" bgcolor="background.default">
      <Routes>
        {/* Public Routes */}
        <Route 
          path="/login" 
          element={!isAuthenticated ? <Login /> : <Navigate to="/dashboard" />} 
        />
        <Route 
          path="/register" 
          element={!isAuthenticated ? <Register /> : <Navigate to="/dashboard" />} 
        />

        {/* Protected Routes */}
        <Route path="/dashboard" element={
          <ProtectedRoute>
            <Dashboard />
          </ProtectedRoute>
        } />

        <Route path="/profile" element={
          <ProtectedRoute>
            <Profile />
          </ProtectedRoute>
        } />

        <Route path="/emergency-contacts" element={
          <ProtectedRoute>
            <EmergencyContacts />
          </ProtectedRoute>
        } />

        <Route path="/alert-history" element={
          <ProtectedRoute>
            <AlertHistory />
          </ProtectedRoute>
        } />

        <Route path="/settings" element={
          <ProtectedRoute>
            <Settings />
          </ProtectedRoute>
        } />

        <Route path="/chat" element={
          <ProtectedRoute>
            <Chat />
          </ProtectedRoute>
        } />

        {/* Admin Routes */}
        <Route path="/admin" element={
          <ProtectedRoute adminOnly>
            <AdminDashboard />
          </ProtectedRoute>
        } />

        {/* Default Route */}
        <Route 
          path="/" 
          element={
            <Navigate to={isAuthenticated ? "/dashboard" : "/login"} />
          } 
        />

        {/* Catch all route */}
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>

      {/* Global Components */}
      <Notification />
      <PWAInstallPrompt />
    </Box>
  );
}

export default App;
